    public static int dtSurvive(byte[] pdf, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells out) {
        // Open, list the pages, and decode every stream the cross-reference
        // names: none of it may fault. Answers the pd-open status.
        int status = dtOpen(pdf, ar, dc, a, b, st, pg);
        int i = 1;
        int h = 0;
        if (status == 0) {
            while (i < Pdfdoc.pdObjectCount(dc)) {
                h = Pdfdoc.pdGet(pdf, ar, dc, a, b, st, i);
                if (h != 0) {
                    if (Pdflex.plKindOf(ar, h) == 8) {
                        Pdfdoc.pdStreamData(pdf, ar, dc, a, b, st, h, out);
                    }
                }
                i += 1;
            }
        }
        return status;
    }
    public static int dtCut(byte[] f, int n, emon.Port.Cells cut) {
        // cut = the first n bytes of f.
        int i = 0;
        emon.Port.cellsDrop(cut, 0);
        while (i < n) {
            emon.Port.cellsPush(cut, emon.Port.blobU8(f, i));
            i += 1;
        }
        return n;
    }
    public static int dtTruncations(byte[] f, int step, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells out, emon.Port.Cells cut) {
        // Every truncation of f (every `step` bytes): none may fault. Answers
        // how many still opened.
        int n = emon.Port.blobLen(f);
        int k = 0;
        int ok = 0;
        while (k <= n) {
            dtCut(f, k, cut);
            if (dtSurvive(emon.Testport.cellsBlob(cut), ar, dc, a, b, st, pg, out) == 0) {
                ok += 1;
            }
            k += step;
        }
        return ok;
    }
    public static int dtCorruptions(byte[] f, int rounds, int flips, int seed, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells out, emon.Port.Cells cut, emon.Port.Cells rng) {
        // `rounds` copies of f, each with `flips` random bytes replaced
        // (SplitMix, so every target damages the same bytes): none may fault.
        int n = emon.Port.blobLen(f);
        int r = 0;
        int j = 0;
        int at = 0;
        int ok = 0;
        Splitmix.smSeed(rng, (long) seed);
        while (r < rounds) {
            dtCut(f, n, cut);
            j = 0;
            while (j < flips) {
                at = Splitmix.smBelow(rng, n);
                emon.Port.cellsSet(cut, at, Splitmix.smBelow(rng, 256));
                j += 1;
            }
            if (dtSurvive(emon.Testport.cellsBlob(cut), ar, dc, a, b, st, pg, out) == 0) {
                ok += 1;
            }
            r += 1;
        }
        return ok;
    }
    public static void testNoTruncationOfAFixtureFaults() {
        emon.Port.Cells ar = emon.Port.newCells();
        emon.Port.Cells dc = emon.Port.newCells();
        emon.Port.Cells a = emon.Port.newCells();
        emon.Port.Cells b = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Port.Cells pg = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells cut = emon.Port.newCells();
        // Every byte of the two small files, and the whole of each: the
        // full file opens, anything cut before its xref does not.
        emon.Testport.assertEq(dtTruncations(emon.Testport.testFile("pdf/minimal.pdf"), 1, ar, dc, a, b, st, pg, out, cut), 8, "minimal: the whole file, and the seven cuts inside its last line (`%%EOF`)");
        emon.Testport.assertThat(dtTruncations(emon.Testport.testFile("pdf/xrefstream.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "xref stream file");
        emon.Testport.assertThat(dtTruncations(emon.Testport.testFile("pdf/hybrid.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "hybrid file");
        emon.Testport.assertThat(dtTruncations(emon.Testport.testFile("pdf/incremental.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "incremental file");
        emon.Testport.assertThat(dtTruncations(emon.Testport.testFile("pdf/filters.pdf"), 1, ar, dc, a, b, st, pg, out, cut) >= 1, "filters file");
    }
